"""English lessons 2-8 and 10. Simple language, one friendly character, concrete facts."""
from scripts.case_authoring.schema import A, L, O

SIMPLE = 'Very simple everyday English. Short sentences. One easy question at a time.'
HELP = ['If the answer is very short, ask one easy question', 'Use the person\'s own words back to them']

LESSONS = [
 L('english-02', 'social', 'beginner', 'A fictional first day at an evening English class.',
   'You meet {{name}}, a new classmate, before an evening English class. {{name}} is from {{city}}. Tell {{name}} about yourself and ask something back.',
   "Hello, I'm {{name}}, your new classmate. I'm from {{city}}. Could you tell me a little about yourself?",
   'Classmate', 'You are a student in an evening English class.', 'Say where you are from, say what you do, and ask {{name}} one question.',
   '{{name}} knows where you are from and what you do, and you asked one question.',
   [A('{{name}}', 'Classmate', 'A new student in your class', 'To make one friend in the class before it starts.', 'Friendly and a little shy.', SIMPLE, HELP, ['class', 'city', 'work', 'study'], 'Is nervous about speaking English in front of the class.')],
   ['The class starts in ten minutes.', ('{{name}} is from {{city}} and works as {{job}}.', 'p1'), ('{{name}} started learning English {{since}}.', 'p1')],
   [O('Find out where the learner is from.', 'The learner says where they are from or where they live.', "I'm from Lahore.", ['Where are you from?', 'Do you live near here?'],
      "We are new classmates. I told you where I'm from. Now please tell me: where are you from?", 'A full short sentence about your home.', 'Giving one word and stopping', 'Use: I am from, or: I live in.', "I'm from Lahore, but I live in Karachi now.", 'Say: I am from, and then your city.', 'vocabulary'),
    O('Find out what the learner does.', 'The learner says what they do or study.', 'I work in a bank.', ['What do you do?', 'Do you work or study?'],
      'Now tell me about your work or your studies. You can say: I work in, or: I study.', 'Saying your job or your studies in a full sentence.', 'Saying only the job word', 'Use: I work in, or: I study.', 'I work in a bank, and I study English at night.', 'Say: I work, or: I study.', 'grammar'),
    O('The learner shows interest by asking back.', 'The learner asks a real question about the classmate.', 'What about you?', ['And I talk a lot! Do you have a question for me?', 'Is there anything you want to ask me?'],
      'Now ask me one question. You can say: What about you?', 'Asking back keeps a conversation going, and shows you are interested.', 'Only answering, and never asking', 'A good chat goes both ways. After you answer, ask back.', 'What about you? What do you do?', 'Say: What about you?', 'comprehension')],
   'Thank you. It was nice to meet you. See you in class!',
   [{'name': 'Maya', 'city': 'Kuala Lumpur', 'job': 'a nurse', 'since': 'last year'}, {'name': 'Bilal', 'city': 'Multan', 'job': 'a driver', 'since': 'in January'}]),

 L('english-03', 'social', 'beginner', 'A fictional chat with a new friend at a family picnic in a park.',
   'You are at a picnic with a new friend, {{name}}. {{name}} lives with {{family}}. Talk about the people close to you, and ask about {{name}}\'s family.',
   "It's so nice here. I came with {{family}}. Who do you live with?",
   'Friend', 'You are at a picnic with a new friend.', 'Talk about someone in your family using words like mother or brother, use he, she or they, and ask about the other person.',
   'Your friend knows about one or two people close to you, and you asked about their family too.',
   [A('{{name}}', 'New friend', 'Someone you met recently', 'To learn about you and to talk about their family.', 'Warm and curious.', SIMPLE, HELP, ['family', 'brother', 'sister', 'mother', 'father'], 'Misses a brother who lives far away.')],
   ['The two of you are at a picnic in the park.', ('{{name}} lives with {{family}}.', 'p1'), ('{{name}} has a brother who lives in {{city}}.', 'p1')],
   [O('Hear who the learner lives with.', 'The learner names at least one family member or close person.', 'I live with my parents.', ['Do you have brothers or sisters?', 'Who is in your family?'],
      'We are talking about family. Tell me one person in your family. You can say: I live with my mother.', 'Naming real people in your life.', 'Answering only yes or no', 'Use family words: mother, father, brother, sister.', 'I live with my parents and my sister.', 'Say one family word.', 'vocabulary'),
    O('Hear something about that person.', 'The learner uses he, she or they correctly about someone.', 'She works in a school.', ['Tell me about one of them. What do they do?', 'What is your sister or brother like?'],
      'Now tell me about that person. Start with he or she. For example: She works in a school.', 'Using he for a man, she for a woman, and they for a group.', 'Mixing up he and she', 'Choose he or she, then say one thing about the person.', 'She is a teacher. She works near our house.', 'Say one sentence starting with he or she.', 'grammar'),
    O('The learner asks back.', 'The learner asks a question about the friend or their family.', 'Do you have a brother?', ['I talk too much! Is there anything you want to know about my family?', 'Do you want to ask me something?'],
      'Now ask me about my family. You can say: Do you have a brother?', 'Asking back shows you care about the other person.', 'Not asking anything', 'Use: Do you have, or: Who do you.', 'Who do you live with? Do you have a brother?', 'Say: Do you have a brother?', 'comprehension')],
   'Thank you. I enjoyed talking with you.',
   [{'name': 'Sana', 'family': 'my mother and my two sisters', 'city': 'Dubai'}, {'name': 'Tom', 'family': 'my wife and our son', 'city': 'Manchester'}]),

 L('english-04', 'social', 'beginner', 'A fictional practice chat with a language partner about normal weekdays.',
   'Your language partner {{name}} wants to compare normal weekdays with you. {{name}} {{routine}}. Tell {{name}} about your day and ask about theirs.',
   'I always find mornings difficult! What does a normal weekday look like for you?',
   'Language partner', 'You are practising English with a partner.', 'Say what you usually do on a weekday, use time words like at seven or after work, and ask about your partner\'s day.',
   'Your partner knows three things you do in a day and when, and you asked about their day.',
   [A('{{name}}', 'Language partner', 'Practises English with you each week', 'To compare daily routines, and to find a good time for the next practice.', 'Cheerful and patient.', SIMPLE, HELP, ['morning', 'work', 'evening', 'routine'], 'Would like to find a regular practice time.')],
   ['You meet each week to practise English.', ('{{name}} {{routine}}.', 'p1')],
   [O('Hear what the learner usually does.', 'The learner describes things they usually do, in the present simple.', 'I usually wake up early and go to work.', ['What do you usually do in the morning?', 'What do you do first?'],
      'Tell me about a normal day. Start with: I usually.', 'Using the present simple for things you do every day.', 'Saying: I am wake up', 'For daily habits use: I wake up, I go, I eat.', 'I usually wake up early, then I go to work.', 'Say: I usually, and one action.', 'grammar'),
    O('Hear when these things happen.', 'The learner uses a time expression.', 'I start work at nine.', ['What time do you do that?', 'And after that?'],
      'Now say when. You can say: at seven, or: in the evening.', 'Time words help the listener follow your day.', 'Leaving out at or in', 'Say: at seven, in the morning, after work.', 'I start work at nine, and in the evening I cook.', 'Say one time: at seven.', 'vocabulary'),
    O('The learner asks about the partner.', 'The learner asks about the partner\'s routine.', 'What time do you get up?', ['My day is very different. Do you want to know about it?', 'Do you have a question about my day?'],
      'Now ask about my day. You can say: What time do you get up?', 'Asking the same question back is an easy way to keep talking.', 'Only talking about yourself', 'Use: What time do you, or: When do you.', 'What time do you get up? When do you finish work?', 'Say: What time do you get up?', 'comprehension')],
   'Thanks. That was good practice. See you next week!',
   [{'name': 'Lina', 'routine': 'starts work at eight and goes for a walk after dinner'}, {'name': 'Omar', 'routine': 'studies in the morning and works in a shop in the evening'}]),

 L('english-05', 'social', 'beginner', 'A fictional chat between friends who are choosing a weekend activity.',
   'You and your friend {{name}} are choosing something to do this weekend. {{name}} likes {{likes}} but does not like {{dislikes}}. Say what you like, say why, and find something you both enjoy.',
   "I'm choosing something for us to do this weekend. I really like {{likes}}. What do you enjoy?",
   'Friend', 'You are choosing a weekend activity with a friend.', 'Say what you like or dislike, give one reason with because, and find one thing you both enjoy.',
   'You have found something you both enjoy, and your friend knows why you like it.',
   [A('{{name}}', 'Friend', 'A friend making weekend plans', 'To find something fun to do together this weekend.', 'Easygoing and cheerful.', SIMPLE, HELP, ['like', 'weekend', 'food', 'film', 'music'])],
   ['You are choosing an activity for this weekend.', ('{{name}} likes {{likes}} and does not like {{dislikes}}.', 'p1')],
   [O('Hear what the learner likes.', 'The learner says what they like or do not like.', 'I like football.', ['Do you like {{likes}}?', 'What do you like to do at the weekend?'],
      'Tell me something you like. You can say: I like, or: I don\'t like.', 'A clear sentence with like, love or enjoy.', 'Saying: I am like', 'Say: I like football. Do not add am.', 'I like football, and I enjoy old films.', 'Say: I like, and one thing.', 'grammar'),
    O('Hear why.', 'The learner gives a reason.', 'I like it because it is relaxing.', ['Oh, why do you like that?', 'What do you like about it?'],
      'Now tell me why. Use the word because.', 'A reason makes your answer more interesting.', 'Giving no reason', 'Add because and your reason.', 'I like football because I can see my friends.', 'Say: because it is fun.', 'vocabulary'),
    O('Find something shared.', 'The learner proposes or agrees on something both enjoy, or asks what the friend likes.', 'We both like films, so let\'s see one.', ['So what should we do together?', 'What do you think we both would like?'],
      'Now find one thing for both of us. Ask me what I like, or say: Let\'s go to.', 'Listening to what the other person likes, and matching it with yours.', 'Only saying what you want', 'Say: We both like, or: Let\'s.', 'We both like food, so let\'s try the new cafe.', 'Say: What do you like?', 'comprehension', signal=r"\b(?:do you like|what do you|which do you|we both|let's|shall we|how about)\b")],
   'Great, that sounds fun. See you at the weekend!',
   [{'name': 'Alex', 'likes': 'old films', 'dislikes': 'very loud music'}, {'name': 'Nimra', 'likes': 'walking in the park', 'dislikes': 'crowded shopping centres'}]),

 L('english-06', 'service', 'beginner', 'A fictional small cafe where the learner orders a meal.',
   'You are ordering at a small cafe. {{menu}} Order politely, ask about something on the menu, and check your order.',
   'Good evening! Here is the menu. What would you like to order?',
   'Customer', 'You are a customer in a small cafe.', 'Order politely, ask one question about the menu, and check that your order is right.',
   'The server knows your order, you asked one question, and you confirmed the order.',
   [A('{{name}}', 'Server', 'Works at the cafe', 'To take a correct order quickly on a busy evening.', 'Polite and busy.', SIMPLE, ['Offer only what is on the menu', 'Read the order back if nobody does'], ['menu', 'food', 'drink', 'order', 'price'])],
   ['{{menu}}', 'Prices are in the local currency.', ('{{name}} recommends the {{special}} today.', 'p1')],
   [O('Take the order.', 'The learner orders politely.', "I'd like a sandwich, please.", ['What would you like?', 'Are you ready to order?'],
      'I am the server. Please tell me what you want from the menu. You can say: I would like.', 'Using would like and please sounds polite and natural.', 'Saying: Give me', "Say: I'd like, and then please.", "I'd like the soup, please.", "Say: I'd like, and one thing.", 'vocabulary'),
    O('Answer a question about the menu.', 'The learner asks about something on the menu.', 'What do you recommend?', ['Is there anything you want to ask about the menu?', 'Do you have any questions?'],
      'You can ask me about the food. You can say: What do you recommend?', 'Asking before you choose is normal in a cafe.', 'Not asking when you are unsure', 'Use: What is, or: How much is.', 'What do you recommend? How much is the soup?', 'Say: What do you recommend?', 'comprehension'),
    O('Check the order.', 'The learner confirms or corrects the order.', "Yes, that's correct, thank you.", ['So, is that everything?', 'Let me check. Is your order correct?'],
      'Now check the order. You can say: Yes, that is correct.', 'A quick check stops mistakes.', 'Staying silent when the order is wrong', "Say: That's correct, or: Sorry, I asked for.", "Yes, that's correct. That's all, thank you.", "Say: That's correct.", 'grammar')],
   'Thank you. Your food will be ready soon.',
   [{'name': 'Sam', 'menu': 'Today the cafe serves tea for 2 and a cheese sandwich for 4. Tomato soup is not available.', 'special': 'cheese sandwich'},
    {'name': 'Hira', 'menu': 'Today the cafe serves coffee for 3 and vegetable soup for 5. Sandwiches are not available.', 'special': 'vegetable soup'}]),

 L('english-07', 'service', 'beginner', 'A fictional clothes shop where the learner buys something they need.',
   'You need {{need}} from a small clothes shop. {{stock}} Say what you need, ask about the price or size, and then buy it or say no politely.',
   'Welcome! What are you looking for today?',
   'Customer', 'You are a customer in a clothes shop.', 'Say what you need, ask about price or size, then buy it or politely say no.',
   'You know the price and size, and you have decided to buy or not.',
   [A('{{name}}', 'Shop assistant', 'Works in the shop', 'To help you find the right thing, and to make a sale if it fits.', 'Helpful and friendly, never pushy.', SIMPLE, ['Say only the prices and sizes you have', 'Accept a polite no happily'], ['shirt', 'jacket', 'size', 'colour', 'price'])],
   ['{{stock}}'],
   [O('Find out what the customer needs.', 'The learner says what they are looking for.', "I'm looking for a shirt.", ['Are you looking for something for you?', 'What do you need today?'],
      "I work in this shop. Tell me what you want to buy. You can say: I'm looking for.", 'Saying what you want clearly, so the assistant can help.', 'Only pointing or saying the word', "Say: I'm looking for.", "I'm looking for a blue shirt.", "Say: I'm looking for, and one thing.", 'vocabulary'),
    O('Answer questions about price and size.', 'The learner asks about price, size or colour.', 'How much is it? Do you have it in medium?', ['Would you like to know the price or the sizes?', 'Do you want to ask me anything about it?'],
      'Now ask me about it. You can say: How much is it?', 'Asking before you buy.', 'Saying: How much it is', 'The order is: How much is it?', 'How much is it? Do you have it in medium?', 'Say: How much is it?', 'grammar'),
    O('Get a decision.', 'The learner accepts or politely declines.', "I'll take it, thank you.", ['So, would you like to take it?', 'What do you think? Do you want it?'],
      "Now decide. You can say: I'll take it, or: No, thank you.", 'A clear, polite decision, whichever it is.', 'Walking away without saying anything', "Say: I'll take it, or: Not today, thank you.", "It's a little expensive, so not today, thank you.", "Say: I'll take it.", 'comprehension')],
   'Thank you for coming. Have a nice day!',
   [{'name': 'Robin', 'need': 'a shirt', 'stock': 'The blue shirt costs 20 and comes in small and medium. The red shirt costs 25 and comes in large.'},
    {'name': 'Asma', 'need': 'a jacket', 'stock': 'The black jacket costs 40 and comes in medium. The green jacket costs 35 and comes in small and large.'}]),

 L('english-08', 'service', 'beginner', 'A fictional street where a visitor asks a local for directions.',
   'You are lost and you need to find {{place}}. {{name}}, who lives nearby, offers to help. Ask the way, check one direction, and repeat the route.',
   'Hi there. You look a little lost. Where are you trying to go?',
   'Visitor', 'You are a visitor, and you are lost in town.', 'Ask how to get to {{place}}, check one direction, and then say the route back.',
   '{{name}} has heard you repeat the route correctly.',
   [A('{{name}}', 'Local resident', 'Lives nearby', 'To help you find the way and then get home.', 'Kind and unhurried.', SIMPLE, ['Give one direction at a time', 'Ask them to say the route back'], ['street', 'left', 'right', 'near', 'walk'])],
   ['You are looking for {{place}}.', ('The way is: {{route}}', 'p1')],
   [O('Find out where the visitor wants to go.', 'The learner asks for directions to a place.', 'How do I get to the library?', ['Where do you want to go?', 'Do you need directions?'],
      'You are lost, and I can help you. Ask me: How do I get to {{place}}?', 'A polite, clear question with the place name.', 'Saying only the place name', 'Say: How do I get to, or: Where is.', 'Excuse me, how do I get to {{place}}?', 'Say: Where is, and the place.', 'vocabulary'),
    O('Give the directions and check them.', 'The learner checks a direction.', 'Do I turn left at the park?', ['Is that clear so far?', 'Do you want me to say that again?'],
      'Ask me to check one thing. You can say: Do I turn left?', 'Checking one direction before you walk away.', 'Saying yes when you did not understand', 'If you are not sure, ask: Do I turn left?', 'Sorry, do I turn left or right?', 'Say: Do I turn left?', 'comprehension'),
    O('Hear the route repeated.', 'The learner repeats the route to confirm it.', 'So I go straight, then turn left.', ['Can you tell me the way back, so I know you have it?', 'So what will you do first?'],
      'Now say the way back to me. Start with: So I go.', 'Saying the route back is the best check of all.', 'Saying only thank you', 'Start with: So I go, then: then I turn.', 'So I go straight, then I turn left beside the park.', 'Say: So I go.', 'grammar')],
   "You've got it. Good luck, and enjoy your day!",
   [{'name': 'Maria', 'place': 'the library', 'route': 'two blocks straight ahead, then left beside the park. It takes ten minutes on foot.'},
    {'name': 'Hamid', 'place': 'the train station', 'route': 'one block straight ahead, then right beside the pharmacy. It takes five minutes on foot.'}]),

 L('english-10', 'social', 'beginner', 'A fictional relaxed conversation over tea with a friendly person from the neighbourhood.',
   'You are having tea with {{name}}, who {{about}}. Keep the conversation going for a few minutes. If you do not understand something, ask.',
   'Hello! Let me get us some tea. How has your day been so far?',
   'Conversation partner', 'You are having tea and a chat with someone new.', 'Answer in full sentences, ask for clarification at least once if you need it, and give a reason with because or more detail.',
   'You kept the conversation going with full answers, at least one question, and at least one reason.',
   [A('{{name}}', 'Conversation partner', 'Lives nearby', 'To have a friendly chat and hear about you.', 'Warm, relaxed and talkative.', 'Simple everyday English, sometimes with one less common word so you can practise asking about it.', ['Use one slightly harder word, so the learner can ask about it', 'Ask follow-up questions'], ['day', 'work', 'family', 'tea', 'hobby'])],
   ['You are having tea together.', ('{{name}} {{about}}.', 'p1'), ('{{name}} has a {{hobby}}.', 'p1')],
   [O('Hear about the learner in full sentences.', 'The learner gives a complete answer of their own.', 'I was busy today because I had two classes.', ['So what did you do today?', 'Tell me about your day.'],
      'We are just chatting. Tell me one thing about your day. Use a full sentence.', 'Full sentences give the other person more to talk about.', 'One-word answers', 'Say a full sentence: I was, I am, or I like.', 'I was busy today. I had two classes.', 'Say: Today I was.', 'grammar', desc=None),
    O('Hear a question or clarification.', 'The learner asks a question or asks for clarification.', 'What do you mean? Could you say that again?', ['I love my hobby, it is quite absorbing. What about you?', 'Is there anything you want to ask me?'],
      'If you do not understand me, you can say: What do you mean? Or ask me something about my day.', 'Asking when you do not understand is a real skill, not a mistake.', 'Pretending to understand', 'Say: Could you say that again? or: What do you mean?', 'Sorry, what does absorbing mean?', 'Say: What do you mean?', 'comprehension'),
    O('Hear more detail.', 'The learner extends an answer with a reason or extra detail.', 'I like it because I can relax.', ['Why do you say that?', 'Tell me a bit more about that.'],
      'Tell me a little more. Use the word because.', 'Adding because turns a short answer into a real conversation.', 'Stopping after one sentence', 'Add because, or add: and then.', 'I like it because I can relax after work.', 'Say: because.', 'vocabulary')],
   'That was lovely. Thank you for the chat!',
   [{'name': 'Mrs Khan', 'about': 'retired last year and lives two streets away', 'hobby': 'small garden'}, {'name': 'Daniel', 'about': 'just moved here for a new job', 'hobby': 'collection of old radios'}]),
]
